import React, { useEffect, useState } from 'react';
import styles from './Dashboard.module.css';
import { fetchPortfolio } from '../../api';

interface PortfolioItem {
  id: number;
  ticker: string;
  amount: number;
  buy_price: number;
  sell_price: number | null;
  buy_date: string;
  sell_date: string | null;
}

const Dashboard = () => {
  const [portfolioData, setPortfolioData] = useState<PortfolioItem[]>([]);
  const [loading, setLoading] = useState<boolean>(true);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    const loadData = async () => {
      try {
        const data = await fetchPortfolio({ active_only: true });

        // Validate data structure
        if (!Array.isArray(data)) {
          throw new Error('Invalid data format from API');
        }

        setPortfolioData(data);
      } catch (err) {
        setError(err instanceof Error ? err.message : 'Unknown error occurred');
      } finally {
        setLoading(false);
      }
    };

    loadData();
  }, []);

  // Safe calculations
  const totalInvested = portfolioData.reduce(
    (sum, item) => sum + (item.amount * item.buy_price),
    0
  );

  const totalCurrentValue = portfolioData.reduce(
    (sum, item) => sum + (item.amount * (item.sell_price || item.buy_price)),
    0
  );

  if (loading) return <div className={styles.loading}>Loading...</div>;
  if (error) return <div className={styles.error}>Error: {error}</div>;

  return (
    <div className={styles.pageLayout}>
      {/* Portfolio Overview */}
      <div className={styles.container}>
        <h1>Portfolio Overview</h1>
        <div className={styles.metrics}>
          <MetricCard 
            title="Total Invested" 
            value={`$${totalInvested.toFixed(2)}`} 
          />
          <MetricCard
            title="Current Value"
            value={`$${totalCurrentValue.toFixed(2)}`}
          />
          <MetricCard
            title="Profit/Loss"
            value={`$${(totalCurrentValue - totalInvested).toFixed(2)}`}
            isProfit={totalCurrentValue >= totalInvested}
          />
        </div>
      </div>

      {/* Data Tables */}
      <div className={styles.dataSection}>
        <PortfolioTable data={portfolioData} />
      </div>
    </div>
  );
};

// Helper components for better organization
const MetricCard = ({ title, value, isProfit }: { title: string; value: string; isProfit?: boolean }) => (
  <div className={`${styles.metricCard} ${isProfit !== undefined ? (isProfit ? styles.profit : styles.loss) : ''}`}>
    <h3>{title}</h3>
    <p>{value}</p>
  </div>
);

const PortfolioTable = ({ data }: { data: PortfolioItem[] }) => (
  <table className={styles.table}>
    <thead>
      <tr>
        <th>Ticker</th>
        <th>Amount</th>
        <th>Buy Price</th>
        <th>Current Value</th>
      </tr>
    </thead>
    <tbody>
      {data.map((item) => (
        <tr key={item.id}>
          <td>{item.ticker}</td>
          <td>{item.amount.toLocaleString()}</td>
          <td>${item.buy_price.toFixed(2)}</td>
          <td>${(item.amount * (item.sell_price || item.buy_price)).toFixed(2)}</td>
        </tr>
      ))}
    </tbody>
  </table>
);

export default Dashboard;
